INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'en', 'Archiving', '[["Two different periods","Invoices and vouchers five years, account books ten, under Commercial Accounting Act art. 38. Storing everything for five is not compliance."],["Retention","Standard Taiwan bookkeeping retention rules apply -- confirm the current period with a tax adviser"],["Signature","Required. The signature is part of what makes the stored document valid, so it must survive archiving intact."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Taiwan') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'es', 'Conservación', '[["Dos plazos distintos","Facturas y comprobantes cinco años; libros contables diez, según el art. 38 de la Ley de Contabilidad Mercantil. Guardarlo todo cinco años no es cumplir."],["Conservación","Se aplican las reglas estándar de conservación contable de Taiwán -- confirme el período vigente con un asesor fiscal"],["Firma","Exigida. La firma forma parte de lo que da validez al documento almacenado, así que debe sobrevivir intacta al archivo."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Taiwan') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', 'Aufbewahrung', '[["Zwei verschiedene Fristen","Rechnungen und Belege fünf Jahre, Geschäftsbücher zehn, nach Art. 38 des Handelsbuchführungsgesetzes. Alles fünf Jahre aufzubewahren ist keine Erfüllung."],["Aufbewahrung","Es gelten die üblichen taiwanischen Aufbewahrungsvorschriften -- aktuelle Frist mit einem Steuerberater klären"],["Signatur","Erforderlich. Die Signatur gehört zur Gültigkeit des gespeicherten Dokuments und muss die Archivierung unversehrt überstehen."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Taiwan') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'fr', 'Conservation', '[["Deux durées différentes","Factures et pièces cinq ans, livres comptables dix, selon l''art. 38 de la loi sur la comptabilité commerciale. Tout garder cinq ans n''est pas se conformer."],["Conservation","Les règles standards de conservation comptable taïwanaises s''appliquent -- vérifiez la durée actuelle avec un conseiller fiscal"],["Signature","Exigée. La signature fait partie de ce qui rend le document stocké valide et doit survivre intacte à l''archivage."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Taiwan') AND d.section = 'file_format' AND d.sort_order = 3;

